'use client'

import { useEffect, useState } from 'react'
import { getActiveAds, incrementAdView, incrementAdClick, Ad } from '@/lib/supabase'
import SafeImage from '@/components/ui/SafeImage'
import { logger } from '@/lib/utils/logger'

interface AdBannerProps {
  position: 'sidebar' | 'header' | 'footer' | 'content'
  className?: string
}

export default function AdBanner({ position, className = '' }: AdBannerProps) {
  const [ads, setAds] = useState<Ad[]>([])
  const [currentAd, setCurrentAd] = useState<Ad | null>(null)

  useEffect(() => {
    loadAds()
  }, [position])

  const loadAds = async () => {
    try {
      const activeAds = await getActiveAds(position)
      setAds(activeAds)
      if (activeAds.length > 0) {
        // Rastgele bir reklam seç
        const randomAd = activeAds[Math.floor(Math.random() * activeAds.length)]
        setCurrentAd(randomAd)

        // #region agent log (debug-mode)
        try {
          const host = (() => {
            try { return new URL(randomAd.image_url).hostname } catch { return 'invalid-url' }
          })()
          fetch('http://127.0.0.1:7242/ingest/9afd2d8d-c796-42ed-ac62-2976d95d1916', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              sessionId: 'debug-session',
              runId: 'pre-fix',
              hypothesisId: 'H1',
              location: 'src/components/ui/AdBanner.tsx:loadAds',
              message: 'AdBanner selected ad',
              data: { position, hasLink: !!randomAd.link_url, imageHost: host },
              timestamp: Date.now(),
            }),
          }).catch(() => {})
        } catch {}
        // #endregion agent log (debug-mode)
        
        // View count'u artır
        if (randomAd.id) {
          await incrementAdView(randomAd.id)
        }
      }
    } catch (error) {
      logger.error('Error loading ads:', error)

      // #region agent log (debug-mode)
      fetch('http://127.0.0.1:7242/ingest/9afd2d8d-c796-42ed-ac62-2976d95d1916', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          sessionId: 'debug-session',
          runId: 'pre-fix',
          hypothesisId: 'H2',
          location: 'src/components/ui/AdBanner.tsx:loadAds:catch',
          message: 'AdBanner loadAds error',
          data: { position, message: String((error as any)?.message || error) },
          timestamp: Date.now(),
        }),
      }).catch(() => {})
      // #endregion agent log (debug-mode)
    }
  }

  const handleClick = async () => {
    if (currentAd?.id) {
      await incrementAdClick(currentAd.id)
      if (currentAd.link_url) {
        window.open(currentAd.link_url, '_blank', 'noopener,noreferrer')
      }
    }
  }

  if (!currentAd) return null

  return (
    <div className={`ad-banner ${className}`}>
      <div
        className="relative cursor-pointer hover:opacity-90 transition-opacity"
        onClick={handleClick}
      >
        {currentAd.link_url ? (
          <a
            href={currentAd.link_url}
            target="_blank"
            rel="noopener noreferrer"
            className="block"
          >
            <SafeImage
              src={currentAd.image_url || 'https://via.placeholder.com/300x250?text=Reklam'}
              alt={currentAd.title || 'Reklam'}
              width={300}
              height={250}
              className="w-full h-auto rounded-lg"
            />
            {currentAd.title && (
              <div className="mt-2 text-xs text-gray-600 text-center">
                {currentAd.title}
              </div>
            )}
          </a>
        ) : (
          <div>
            <SafeImage
              src={currentAd.image_url || 'https://via.placeholder.com/300x250?text=Reklam'}
              alt={currentAd.title || 'Reklam'}
              width={300}
              height={250}
              className="w-full h-auto rounded-lg"
            />
            {currentAd.title && (
              <div className="mt-2 text-xs text-gray-600 text-center">
                {currentAd.title}
              </div>
            )}
          </div>
        )}
        <div className="absolute top-2 right-2 bg-black/50 text-white text-xs px-2 py-1 rounded">
          Reklam
        </div>
      </div>
    </div>
  )
}
